	    {   
			ObjectTable ShipmentCommodityObjectTable = ObjectContext.ObjectTables.Where(d => d.Name == "ShipmentCommodity" && d.Tenant == 0).FirstOrDefault(); 
            AddEventTypes.AddEventType(new EventTypeDetails()
